    // Codec=Sse (Serialization based), see doc to use other codecs
    var var_epoch = sse_decode_i_32(deserializer);
    var var_trainLoss = sse_decode_f_32(deserializer);
    var var_testLoss = sse_decode_f_32(deserializer);
    var var_trainAccuracy = sse_decode_f_32(deserializer);
    var var_testAccuracy = sse_decode_f_32(deserializer);
    var var_weightsSummary = sse_decode_list_list_list_prim_f_32_strict(
      deserializer,
    );
    var var_biasesSummary = sse_decode_list_list_prim_f_32_strict(deserializer);
    var var_decisionBoundary = sse_decode_list_prim_f_32_strict(deserializer);
    var var_neuronActivationsGrid = sse_decode_list_list_prim_f_32_strict(
      deserializer,
    );
    var var_landscape3D = sse_decode_opt_box_autoadd_loss_landscape_3_d(
      deserializer,
    );
    return TrainingEpochResult(
      epoch: var_epoch,
      trainLoss: var_trainLoss,
      testLoss: var_testLoss,
      trainAccuracy: var_trainAccuracy,
      testAccuracy: var_testAccuracy,
      weightsSummary: var_weightsSummary,
      biasesSummary: var_biasesSummary,
      decisionBoundary: var_decisionBoundary,
      neuronActivationsGrid: var_neuronActivationsGrid,
      landscape3D: var_landscape3D,
    );
  }

