  @protected
  void sse_encode_loss_landscape_3_d(
    LossLandscape3D self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_usize(self.gridSize, serializer);
    sse_encode_f_32(self.w1Min, serializer);
    sse_encode_f_32(self.w1Max, serializer);
    sse_encode_f_32(self.w2Min, serializer);
    sse_encode_f_32(self.w2Max, serializer);
    sse_encode_list_prim_f_32_strict(self.lossGrid, serializer);
    sse_encode_f_32(self.currentW1, serializer);
    sse_encode_f_32(self.currentW2, serializer);
    sse_encode_f_32(self.currentLoss, serializer);
  }

