    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_list_layer_config(self.layers, serializer);
    sse_encode_f_32(self.learningRate, serializer);
    sse_encode_f_32(self.momentum, serializer);
    sse_encode_String(self.regularization, serializer);
    sse_encode_f_32(self.regRate, serializer);
    sse_encode_String(self.problemType, serializer);
  }

