    sse_encode_bool(self != null, serializer);
    if (self != null) {
      sse_encode_box_autoadd_loss_landscape_3_d(self, serializer);
    }
  }

  @protected
  void sse_encode_training_epoch_result(
    TrainingEpochResult self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.epoch, serializer);
    sse_encode_f_32(self.trainLoss, serializer);
    sse_encode_f_32(self.testLoss, serializer);
    sse_encode_f_32(self.trainAccuracy, serializer);
    sse_encode_f_32(self.testAccuracy, serializer);
    sse_encode_list_list_list_prim_f_32_strict(self.weightsSummary, serializer);
    sse_encode_list_list_prim_f_32_strict(self.biasesSummary, serializer);
    sse_encode_list_prim_f_32_strict(self.decisionBoundary, serializer);
    sse_encode_list_list_prim_f_32_strict(
      self.neuronActivationsGrid,
      serializer,
    );
    sse_encode_opt_box_autoadd_loss_landscape_3_d(self.landscape3D, serializer);
  }

